//! Issue-17 planned corpus structure: eight target ids, exact desired 100-card
//! lists, honest missing-card accounting. Planned lists are not supported.

use std::collections::BTreeSet;
use std::path::PathBuf;

use aperture_core::DeckList;
use aperture_core::catalog;
use aperture_import::commander::{LegalityStatus, SupportStatus, analyze_snapshots};
use serde_json::Value;

const MANIFEST: &str = include_str!("../../../decks/starter-corpus/manifest.json");
const NOW: u64 = 1_793_000_000;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn read(path: &str) -> String {
    std::fs::read_to_string(root().join(path)).unwrap_or_else(|e| panic!("{path}: {e}"))
}

#[test]
fn eight_targets_have_exact_desired_lists_and_honest_missing_cards() {
    let manifest: Value = serde_json::from_str(MANIFEST).expect("manifest parses");
    assert_eq!(manifest["version"], 1);
    let starters = manifest["starters"].as_array().expect("starters");
    assert_eq!(starters.len(), 8);
    let expected_ids = [
        "isamaru-white-aggro",
        "jasmine-vanilla-stompy",
        "talrand-draw-go",
        "krenko-goblin-tokens",
        "ayula-bear-counters",
        "elas-sacrifice",
        "tatyova-landfall",
        "zada-spells",
    ];
    let ids: Vec<&str> = starters
        .iter()
        .map(|starter| starter["id"].as_str().expect("id"))
        .collect();
    assert_eq!(ids, expected_ids);

    let mut planned = 0;
    for starter in starters {
        let id = starter["id"].as_str().unwrap();
        let status = starter["status"].as_str().unwrap();
        assert!(matches!(status, "planned" | "implemented" | "certified"));
        assert_ne!(status, "certified", "{id} is not certified");
        let deck_path = starter["deck_path"]
            .as_str()
            .unwrap_or_else(|| panic!("{id} has no exact desired list"));
        let commander = starter["commander"].as_str().unwrap();
        let deck = DeckList::parse_practice(id, &read(deck_path))
            .unwrap_or_else(|e| panic!("{id} desired list parses: {e}"));
        assert_eq!(deck.size(), 99, "{id} library");
        let lands = deck.lands();
        assert!((38..=43).contains(&lands), "{id} basic lands {lands}");
        let mut nonland = BTreeSet::new();
        for (card, quantity) in &deck.cards {
            if card.def().is_land() {
                assert!(
                    card.def().basic_mana.is_some(),
                    "{id}: only basic lands may repeat"
                );
                continue;
            }
            assert_eq!(*quantity, 1, "{id}: {} must be singleton", card.name());
            assert!(nonland.insert(card.name()), "{id}: duplicate nonbasic");
        }
        assert!(
            (56..=61).contains(&nonland.len()),
            "{id}: {} unique nonland names",
            nonland.len()
        );
        assert_eq!(
            deck.count_of(catalog::by_name(commander).unwrap_or(catalog::all()[0].id)),
            if catalog::by_name(commander).is_some() {
                deck.count_of(catalog::by_name(commander).unwrap())
            } else {
                0
            },
            "{id}: commander must be separate from the library"
        );

        // missing_cards is computed from the current catalog, not invented.
        let mut actual_missing: BTreeSet<String> = vec![commander.to_string()]
            .into_iter()
            .chain(nonland.iter().map(|name| name.to_string()))
            .filter(|name| catalog::by_name(name).is_none())
            .collect();
        actual_missing.extend(
            deck.cards
                .iter()
                .filter(|(card, _)| !card.def().is_land() && catalog::all().iter().all(|d| d.id != card.id))
                .map(|(card, _)| card.name().to_string()),
        );
        let declared: BTreeSet<String> = starter["missing_cards"]
            .as_array()
            .unwrap()
            .iter()
            .map(|name| name.as_str().unwrap().to_string())
            .collect();
        assert_eq!(declared, actual_missing, "{id}: missing_cards must match the catalog");

        if id != "jasmine-vanilla-stompy" {
            planned += 1;
            assert_eq!(status, "planned", "{id} is planned, not supported");
            assert!(
                !declared.is_empty(),
                "{id} must name its unsupported cards"
            );

            // Offline analyzer: format-legal is expected; engine support must be
            // refused honestly.
            let deck_json = read(&format!(
                "fixtures/starter-corpus/planned/{id}.deck.json"
            ));
            let cards_json = read(&format!(
                "fixtures/starter-corpus/planned/{id}.cards.json"
            ));
            let report = analyze_snapshots(&deck_json, &cards_json, NOW)
                .unwrap_or_else(|e| panic!("{id} analyzer: {e}"));
            assert_eq!(report.deck.total, 100, "{id} analyzer total");
            assert_eq!(
                report.status,
                LegalityStatus::Legal,
                "{id} format: {:#?}",
                report.findings
            );
            assert_eq!(
                report.engine_support.status,
                SupportStatus::Unsupported,
                "{id} must not claim support it does not have"
            );
            assert!(!report.engine_support.unsupported_cards.is_empty());
            assert!(!report.gameplay.available);
        } else {
            assert_eq!(status, "implemented");
        }
    }
    assert_eq!(planned, 7);
}

